PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry depthwise_conv2d_kernel(
    .param .u64 input_ptr,
    .param .u64 weight_ptr,
    .param .u64 bias_ptr,
    .param .u64 output_ptr,
    .param .s32 batch,
    .param .s32 channels,
    .param .s32 in_h,
    .param .s32 in_w,
    .param .s32 out_h,
    .param .s32 out_w,
    .param .s32 kernel_size,
    .param .s32 stride,
    .param .s32 padding,
    .param .s32 dilation,
    .param .s32 use_bias
)
{
    .reg .s32 %r<60>;
    .reg .s64 %rd<30>;
    .reg .f32 %f<10>;
    .reg .pred %p<20>;

    ld.param.u64 %rd1, [input_ptr];
    ld.param.u64 %rd2, [weight_ptr];
    ld.param.u64 %rd3, [bias_ptr];
    ld.param.u64 %rd4, [output_ptr];
    ld.param.s32 %r1, [batch];
    ld.param.s32 %r2, [channels];
    ld.param.s32 %r3, [in_h];
    ld.param.s32 %r4, [in_w];
    ld.param.s32 %r5, [out_h];
    ld.param.s32 %r6, [out_w];
    ld.param.s32 %r7, [kernel_size];
    ld.param.s32 %r8, [stride];
    ld.param.s32 %r9, [padding];
    ld.param.s32 %r10, [dilation];
    ld.param.s32 %r11, [use_bias];

    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;
    cvta.to.global.u64 %rd4, %rd4;

    mov.u32 %r12, %ctaid.x;
    mov.u32 %r13, %ntid.x;
    mov.u32 %r14, %tid.x;
    mad.lo.s32 %r15, %r12, %r13, %r14;   // ow

    mov.u32 %r16, %ctaid.y;
    mov.u32 %r17, %ntid.y;
    mov.u32 %r18, %tid.y;
    mad.lo.s32 %r19, %r16, %r17, %r18;   // oh

    mov.u32 %r20, %ctaid.z;              // bc

    setp.ge.s32 %p1, %r15, %r6;
    setp.ge.s32 %p2, %r19, %r5;
    or.pred %p3, %p1, %p2;
    @%p3 bra DONE;

    div.s32 %r21, %r20, %r2;             // b
    mul.lo.s32 %r22, %r21, %r2;
    sub.s32 %r23, %r20, %r22;            // c

    mul.lo.s32 %r24, %r15, %r8;
    sub.s32 %r25, %r24, %r9;             // iw

    setp.lt.s32 %p4, %r25, 0;
    setp.ge.s32 %p5, %r25, %r4;
    or.pred %p6, %p4, %p5;               // iw invalid

    mul.lo.s32 %r26, %r3, %r4;           // in_h*in_w
    mul.lo.s32 %r27, %r2, %r26;          // channels*in_h*in_w

    mul.lo.s32 %r28, %r21, %r27;         // b*batch_stride
    mul.lo.s32 %r29, %r23, %r26;         // c*channel_stride
    add.s32 %r30, %r28, %r29;            // base offset elements

    mul.lo.s32 %r31, %r23, %r7;          // weight base = c*kernel_size

    mov.s32 %r32, 0;                     // kh
    mov.f32 %f1, 0f00000000;             // acc

LOOP_START:
    setp.ge.s32 %p7, %r32, %r7;
    @%p7 bra LOOP_END;

    mul.lo.s32 %r33, %r19, %r8;
    sub.s32 %r34, %r33, %r9;
    mul.lo.s32 %r35, %r32, %r10;
    add.s32 %r36, %r34, %r35;            // ih

    setp.lt.s32 %p8, %r36, 0;
    setp.ge.s32 %p9, %r36, %r3;
    or.pred %p10, %p8, %p9;
    or.pred %p11, %p10, %p6;             // skip flag

    mov.f32 %f2, 0f00000000;
    @%p11 bra SKIP_LOAD;

    mul.lo.s32 %r37, %r36, %r4;
    add.s32 %r38, %r30, %r37;
    add.s32 %r39, %r38, %r25;

    mul.wide.s32 %rd10, %r39, 4;
    add.s64 %rd11, %rd1, %rd10;
    ld.global.f32 %f2, [%rd11];

SKIP_LOAD:
    add.s32 %r40, %r31, %r32;
    mul.wide.s32 %rd12, %r40, 4;
    add.s64 %rd13, %rd2, %rd12;
    ld.global.f32 %f3, [%rd13];

    fma.rn.f32 %f1, %f2, %f3, %f1;

    add.s32 %r32, %r32, 1;
    bra LOOP_START;

LOOP_END:
    setp.eq.s32 %p12, %r11, 0;
    @%p12 bra NO_BIAS;

    mul.wide.s32 %rd14, %r23, 4;
    add.s64 %rd15, %rd3, %rd14;
    ld.global.f32 %f4, [%rd15];
    add.f32 %f1, %f1, %f4;

NO_BIAS:
    mul.lo.s32 %r41, %r5, %r6;           // out_h*out_w
    mul.lo.s32 %r42, %r2, %r41;          // channels*out_h*out_w
    mul.lo.s32 %r43, %r21, %r42;         // b*that
    mul.lo.s32 %r44, %r23, %r41;         // c*out_h*out_w
    add.s32 %r45, %r43, %r44;
    mul.lo.s32 %r46, %r19, %r6;          // oh*out_w
    add.s32 %r47, %r45, %r46;
    add.s32 %r48, %r47, %r15;            // + ow

    mul.wide.s32 %rd16, %r48, 4;
    add.s64 %rd17, %rd4, %rd16;
    st.global.f32 [%rd17], %f1;

DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("depthwise_conv2d_kernel")

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, kernel_size: int, stride: int = 1,
                 padding: int = 0, dilation: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.has_bias = bias

        self.weight = nn.Parameter(torch.empty(in_channels, 1, kernel_size, 1))
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))

        if bias:
            self.bias = nn.Parameter(torch.empty(in_channels))
            fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
            bound = 1 / math.sqrt(fan_in) if fan_in > 0 else 0
            nn.init.uniform_(self.bias, -bound, bound)
        else:
            self.register_parameter('bias', None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.contiguous()
        batch, channels, in_h, in_w = x.shape
        weight = self.weight.contiguous()

        kernel_size = self.kernel_size
        stride = self.stride
        padding = self.padding
        dilation = self.dilation

        out_h = (in_h + 2 * padding - dilation * (kernel_size - 1) - 1) // stride + 1
        out_w = (in_w + 2 * padding - 1) // stride + 1

        output = torch.empty((batch, channels, out_h, out_w),
                              dtype=x.dtype, device=x.device)

        module = _get_ptx_module()

        block = (16, 16, 1)
        grid_x = (out_w + block[0] - 1) // block[0]
        grid_y = (out_h + block[1] - 1) // block[1]
        grid_z = batch * channels

        use_bias_flag = 1 if self.bias is not None else 0
        bias_tensor = self.bias.contiguous() if self.bias is not None else weight

        module.launch(
            "depthwise_conv2d_kernel",
            grid=(grid_x, grid_y, grid_z),
            block=block,
            arguments=[
                x,
                weight,
                bias_tensor,
                output,
                i32(batch),
                i32(channels),
                i32(in_h),
                i32(in_w),
                i32(out_h),
                i32(out_w),
                i32(kernel_size),
                i32(stride),
                i32(padding),
                i32(dilation),
                i32(use_bias_flag),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )

