    mul.lo.s32 %r41, %r5, %r6;           // out_h*out_w
    mul.lo.s32 %r42, %r2, %r41;          // channels*out_h*out_w
    mul.lo.s32 %r43, %r21, %r42;         // b*that
    mul.lo.s32 %r44, %r23, %r41;         // c*out_h*out_w
    add.s32 %r45, %r43, %r44;
    mul.lo.s32 %r46, %r19, %r6;          // oh*out_w
    add.s32 %r47, %r45, %r46;
    add.s32 %r48, %r47, %r15;            // + ow

    mul.wide.s32 %rd16, %r48, 4;
    add.s64 %rd17, %rd4, %rd16;
    st.global.f32 [%rd17], %f1;

DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("depthwise_conv2d_kernel")

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, kernel_size: int, stride: int = 1,
                 padding: int = 0, dilation: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.has_bias = bias

        self.weight = nn.Parameter(torch.empty(in_channels, 1, kernel_size, 1))
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))

        if bias:
            self.bias = nn.Parameter(torch.empty(in_channels))
            fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
            bound = 1 / math.sqrt(fan_in) if fan_in > 0 else 0
            nn.init.uniform_(self.bias, -bound, bound)
        else:
            self.register_parameter('bias', None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.contiguous()
        batch, channels, in_h, in_w = x.shape
        weight = self.weight.contiguous()

        kernel_size = self.kernel_size
        stride = self.stride
        padding = self.padding
        dilation = self.dilation

        out_h = (in_h + 2 * padding - dilation * (kernel_size - 1) - 1) // stride + 1
        out_w = (in_w + 2 * padding - 1) // stride + 1

        output = torch.empty((batch, channels, out_h, out_w),
                              dtype=x.dtype, device=x.device)

        module = _get_ptx_module()

        block = (16, 16, 1)
        grid_x = (out_w + block[0] - 1) // block[0]
        grid_y = (out_h + block[1] - 1) // block[1]
        grid_z = batch * channels

        use_bias_flag = 1 if self.bias is not None else 0
        bias_tensor = self.bias.contiguous() if self.bias is not None else weight

        module.launch(
            "depthwise_conv2d_kernel",
            grid=(grid_x, grid_y, grid_z),
            block=block,
            arguments=[
                x,
                weight,
                bias_tensor,
                output,
                i32(batch),
                i32(channels),
                i32(in_h),
                i32(in_w),
                i32(out_h),
                i32(out_w),
                i32(kernel_size),
                i32(stride),
                i32(padding),
                i32(dilation),
                i32(use_bias_flag),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )

        return output
